<?php

declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';
use InaudisVote\Core\Authorization;use InaudisVote\Core\Csrf;use InaudisVote\Services\ElectionService;
$user=Authorization::requireRoles(['admin','organizer']);$id=(int)($_GET['id']??0);$election=ElectionService::find($id);if(!$election||!Authorization::canManageElection($user,(int)$election['organization_id'])){http_response_code(404);exit('Votación no encontrada.');}$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::validate($_POST['_csrf']??null)){$error='Solicitud inválida.';}else{try{$action=(string)($_POST['action']??'');if($action==='add_question')ElectionService::addQuestion($id,$_POST);if($action==='delete_question')ElectionService::deleteQuestion($id,(int)($_POST['question_id']??0));if($action==='status')ElectionService::setStatus($id,(string)($_POST['status']??''));header('Location: /election.php?id='.$id.'&ok=1');exit;}catch(Throwable $e){$error=$e->getMessage();}}}$election=ElectionService::find($id);$questions=ElectionService::questions($id);$editable=in_array($election['status'],['draft','scheduled'],true)&&empty($election['ballot_locked_at']);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($election['title'])?> | INAUDIS Vote</title><script src="https://cdn.tailwindcss.com"></script></head><body class="min-h-screen bg-slate-950 text-slate-100"><main class="max-w-7xl mx-auto p-6"><nav class="mb-8 flex flex-wrap gap-4 text-sm"><a href="/elections.php" class="text-cyan-400">← Votaciones</a><a href="/census.php?election_id=<?=$id?>">Censo</a><a href="/results.php?election_id=<?=$id?>">Resultados</a><a href="/dashboard.php">Dashboard</a></nav><div class="flex flex-wrap justify-between gap-5 mb-6"><div><p class="text-sm text-cyan-400"><?=htmlspecialchars($election['organization_name'])?></p><h1 class="text-3xl font-semibold"><?=htmlspecialchars($election['title'])?></h1><p class="text-slate-400 mt-2"><?=htmlspecialchars((string)$election['description'])?></p></div><span class="px-3 py-2 rounded-lg bg-slate-900 border border-slate-700 uppercase text-sm"><?=htmlspecialchars($election['status'])?></span></div><?php if(isset($_GET['ok'])):?><div class="mb-5 p-3 bg-emerald-950 border border-emerald-800 rounded">Cambio guardado.</div><?php endif;?><?php if($error):?><div class="mb-5 p-3 bg-red-950 border border-red-800 rounded"><?=htmlspecialchars($error)?></div><?php endif;?><?php if(!$editable):?><div class="mb-5 p-3 bg-amber-950 border border-amber-800 rounded">Papeleta bloqueada. Al abrir una votación ya no se permiten cambios estructurales.</div><?php endif;?><div class="grid lg:grid-cols-3 gap-6"><section class="lg:col-span-2 space-y-4"><div class="bg-slate-900 border border-slate-800 rounded-2xl p-5"><h2 class="font-semibold mb-4">Papeleta</h2><?php if(!$questions):?><p class="text-slate-400">Agrega la primera pregunta.</p><?php endif;?><?php foreach($questions as $q):?><article class="border border-slate-800 rounded-xl p-4 mb-3"><div class="flex justify-between gap-3"><div><h3 class="font-medium"><?=htmlspecialchars($q['text'])?></h3><p class="text-xs text-slate-500 mb-2"><?=htmlspecialchars($q['question_type'])?> · máximo <?=$q['max_choices']?></p></div><?php if($editable):?><form method="post" onsubmit="return confirm('¿Eliminar esta pregunta?');"><?=Csrf::input()?><input type="hidden" name="action" value="delete_question"><input type="hidden" name="question_id" value="<?=$q['id']?>"><button class="text-red-300 text-sm">Eliminar</button></form><?php endif;?></div><ul class="space-y-1 text-sm text-slate-300"><?php foreach($q['options'] as $o):?><li>• <?=htmlspecialchars($o['label'])?></li><?php endforeach;?></ul></article><?php endforeach;?></div><?php if($editable):?><div class="bg-slate-900 border border-slate-800 rounded-2xl p-5"><h2 class="font-semibold mb-4">Agregar pregunta</h2><form method="post" class="space-y-3"><?=Csrf::input()?><input type="hidden" name="action" value="add_question"><textarea name="text" required placeholder="Pregunta" class="w-full bg-slate-950 border border-slate-700 rounded-lg p-3"></textarea><select name="question_type" class="w-full bg-slate-950 border border-slate-700 rounded-lg p-3"><option value="single">Selección única</option><option value="multiple">Selección múltiple</option></select><input type="number" name="max_choices" min="1" value="1" class="w-full bg-slate-950 border border-slate-700 rounded-lg p-3"><textarea name="options" required placeholder="Una alternativa por línea" rows="5" class="w-full bg-slate-950 border border-slate-700 rounded-lg p-3"></textarea><button class="bg-cyan-400 text-slate-950 font-semibold rounded-lg px-5 py-3">Agregar</button></form></div><?php endif;?></section><aside class="space-y-4"><div class="bg-slate-900 border border-slate-800 rounded-2xl p-5"><h2 class="font-semibold mb-4">Estado del proceso</h2><form method="post" class="space-y-3"><?=Csrf::input()?><input type="hidden" name="action" value="status"><select name="status" class="w-full bg-slate-950 border border-slate-700 rounded-lg p-3"><?php foreach(['draft'=>'Borrador','scheduled'=>'Programada','open'=>'Abierta','closed'=>'Cerrada','cancelled'=>'Cancelada'] as $v=>$label):?><option value="<?=$v?>" <?=$election['status']===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select><button class="w-full border border-cyan-500 text-cyan-300 rounded-lg p-3">Actualizar estado</button></form></div><div class="bg-slate-900 border border-slate-800 rounded-2xl p-5 text-sm"><h2 class="font-semibold mb-3">Configuración</h2><p>Modo: <strong><?=htmlspecialchars($election['voting_mode'])?></strong></p><p>Ponderado: <strong><?=$election['allow_weighted_vote']?'Sí':'No'?></strong></p><p>Inicio: <?=htmlspecialchars((string)$election['starts_at'])?></p><p>Término: <?=htmlspecialchars((string)$election['ends_at'])?></p></div></aside></div></main></body></html>